const body = $input.first().json.body || {};
const timestamp = body.timestamp || new Date().toISOString();
const reply = String(body.reply ?? '').trim();
const userMessage = String(body.userMessage ?? '').trim();
const emotion = body.emotion ?? {};
const affinity = body.affinity ?? {};
// O servidor manda {emotion, confidence, ...} e {affinity, stage}. Os nomes
// label e score eram a aposta antiga deste no e nunca existiram no evento.
const emotionLabel = emotion.label ?? emotion.emotion ?? 'neutral';
const affinityScore = affinity.score ?? affinity.affinity ?? 0;
const affinityStage = affinity.stage ?? 'desconhecido';
const actions = body.actions ?? [];
const source = body.source ?? 'desconhecido';

if (!reply && !userMessage) {
  throw new Error('Evento sem conteúdo (reply ou userMessage).');
}

const createdAt = new Date(timestamp).toISOString();
const ts = createdAt.replace(/[:.]/g, '-');
const slug = (userMessage || reply).slice(0, 60)
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 60) || 'evento';
const filename = `${ts}-${slug}.md`;

const actionSummary = actions
  .map(a => `- ${a.type}: ${a.name ?? ''}${a.value !== undefined ? ' → ' + a.value : ''}${a.delayMs !== undefined ? ' (+' + a.delayMs + 'ms)' : ''}`)
  .join('\n') || '(nenhuma ação)';
const markdown = `---\nsource: usami-response\nkind: chat-reply\ncreated_at: ${createdAt}\nuser_message: ${JSON.stringify(userMessage)}\nemotion_label: ${JSON.stringify(emotionLabel)}\nemotion_confidence: ${emotion.confidence ?? 0}\naffinity_score: ${affinityScore}\naffinity_stage: ${JSON.stringify(affinityStage)}\nresponse_source: ${JSON.stringify(source)}\nactions_count: ${actions.length}\n---\n\n## Resposta da Usami\n\n${reply || '(sem texto)'}\n\n## Ações de animação\n\n${actionSummary}\n\n---\n_Evento recebido via webhook usami-events às ${createdAt}_\n`;

return [{ json: { filename, markdown, userMessage, reply, emotion, affinity, actions, source, timestamp: createdAt } }];
